     #########= sorted(P)
     K = sorted(I)

     W = 0
     ik = 0
     for n in N:
         while ik < len(K) and K[ik] < n:
             ik += 1
             W += 1
         ik += 1

     D = 0
     i = 0
     for k in K:
         while i < len(N) and N[i] < k:
             i += 1
         i += 1
         if i <= len(N):
             D += 1

     return 'Case #%s: %s %s\n' % (testcase, D, W)

