 		M = int(temp[1])
 		L = []

 		for i in range(N):
 			L.append(inF.readline().strip().split()) #using an array should speed up the lookups
 			for j in range(M):
 				L[i][j] = int(L[i][j])

 		for y in range(N):
 			for x in range(M):
 				# check horizontal
 				for i in range(M):
 					if L[y][i] > L[y][x]:
 						break
 				else:
 					continue

 				# check vertical
 				for i in range(N):
 					if L[i][x] > L[y][x]:
 						break
 				else:
 					continue
 				break
 			else:
 				continue
 			break
