 def solve(C, F, X, rate=2.0):
 	accum = 0
 	while 1:
 		goal1 = X / rate

 		farm = C / rate
 		goal2 = farm + (X / (rate + F))

 		if goal1 <= goal2:
 			return accum + goal1
 		else:
 			accum += farm
 			rate += F


