 def aux(n, a, b):
     res = 0
     s = set()
     for i in range(1, len(n)):
         m = n[i:]+n[:i]
         if m > n and m >= a and m <= b and m not in s:
             res += 1
             s.add(m)
     return res

 def solve_small(case):
     (A, B) = case
     a = str(A)
     b = str(B)
     res = 0
     for n in range(A, B+1):
         res += aux(str(n), a, b)
     return res

